mapper.select:
SELECT sr.record_date AS date, MAX(CASE WHEN sr.type='INCOME' THEN 1 ELSE 0 END) AS hasIncome, MAX(CASE WHEN sr.type='EXPENSE' THEN 1 ELSE 0 END) AS hasExpense, MAX(CASE WHEN sr.type='SAVING' THEN 1 ELSE 0 END) AS hasSaving FROM service_record sr WHERE sr.user_id IN ( SELECT #{userId} UNION SELECT CASE WHEN c.groom_id = #{userId} THEN c.bride_id ELSE c.groom_id END FROM couple c WHERE c.status='CONNECTED' AND (c.groom_id=#{userId} OR c.bride_id=#{userId}) ) AND sr.record_date BETWEEN #{start} AND #{end} AND ( CASE WHEN sr.changed_category IS NOT NULL THEN sr.changed_category ELSE sr.category END ) IN
#{category}
GROUP BY sr.record_date ORDER BY sr.record_date

SELECT sr.id AS recordId, sr.type AS type, CASE WHEN sr.changed_category IS NOT NULL THEN sr.changed_category ELSE sr.category END AS category, sr.amount, sr.memo, u.name AS owner FROM service_record sr INNER JOIN user u ON sr.user_id = u.id WHERE sr.record_date = #{date} AND sr.user_id IN ( SELECT #{userId} UNION SELECT CASE WHEN c.groom_id = #{userId} THEN c.bride_id ELSE c.groom_id END FROM couple c WHERE c.status='CONNECTED' AND (c.groom_id=#{userId} OR c.bride_id=#{userId}) ) AND ( CASE WHEN sr.changed_category IS NOT NULL THEN sr.changed_category ELSE sr.category END ) IN
#{category}
ORDER BY sr.updated_at DESC
